import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextLong();
        long best = a[0], cur = a[0];
        int bl = 0, br = 0, cl = 0;
        for (int i = 1; i < n; i++) {
            if (a[i] > cur + a[i]) {
                cur = a[i];
                cl = i;
            } else {
                cur += a[i];
            }
            if (cur > best || (cur == best && (cl < bl || (cl == bl && (i - cl) < (br - bl))))) {
                best = cur;
                bl = cl;
                br = i;
            }
        }
        System.out.println(best + " " + bl + " " + br);
    }
}

