import java.util.*;

public class Main {
    static final long MOD = 1000000007L;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = ((sc.nextLong() % MOD) + MOD) % MOD;
        long[] res = new long[n];
        long pref = 1;
        for (int i = 0; i < n; i++) {
            res[i] = pref;
            pref = (pref * a[i]) % MOD;
        }
        long suf = 1;
        for (int i = n - 1; i >= 0; i--) {
            res[i] = (res[i] * suf) % MOD;
            suf = (suf * a[i]) % MOD;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(res[i]);
        }
        System.out.println(sb.toString());
    }
}
